export const PAD_LABELS=Object.freeze({forward:'Throttle',reverse:'Brake / reverse',jump:'Jump / dodge',boost:'Boost',drift:'Powerslide',rollLeft:'Air roll left',rollRight:'Air roll right',camera:'Ball camera',scoreboard:'Scoreboard',pause:'Pause',reset:'Practice reset',next:'Next drill',quickchat:'Quick chat',chat:'Text chat'});
export const PAD_DEFAULTS=Object.freeze({forward:7,reverse:6,jump:0,boost:1,drift:2,rollLeft:4,rollRight:5,camera:3,scoreboard:8,pause:9,reset:12,next:13,quickchat:14,chat:15});
export const PAD_BUTTONS=Object.freeze(['A / Cross','B / Circle','X / Square','Y / Triangle','LB / L1','RB / R1','LT / L2','RT / R2','View / Share','Menu / Options','Left stick / L3','Right stick / R3','D-pad Up','D-pad Down','D-pad Left','D-pad Right']);
export function gamepadPreferences(value={}){const buttons=Object.fromEntries(Object.entries(PAD_DEFAULTS).map(([key,fallback])=>[key,Number.isInteger(value?.buttons?.[key])&&value.buttons[key]>=-1&&value.buttons[key]<16?value.buttons[key]:fallback])),used=Object.values(buttons).filter(n=>n>=0);if(new Set(used).size!==used.length)Object.assign(buttons,PAD_DEFAULTS);const axis=(key,fallback)=>Number.isInteger(value?.[key])&&value[key]>=0&&value[key]<6?value[key]:fallback;return {buttons,steerAxis:axis('steerAxis',0),pitchAxis:axis('pitchAxis',1),lookX:axis('lookX',2),lookY:axis('lookY',3),invertSteering:value?.invertSteering===true,invertLookY:value?.invertLookY===true};}
export const controllerFamily=id=>/dualsense|dualshock|playstation|sony|054c/i.test(id||'')?'PLAYSTATION':/xbox|xinput|045e/i.test(id||'')?'XBOX':'STANDARD GAMEPAD';
